@charset "utf-8";

.ns-lletm-l-landscapePortraitImageLayout { opacity: 1; position: relative; }

.ns-lletm-e-1 { background-color: rgb(255, 255, 255); opacity: 1; }

.ns-lletm-e-2 { background-color: rgb(251, 233, 240); }

.ns-lletm-e-4, .ns-lletm-e-6 { white-space: nowrap; }

.ns-lletm-e-9 { border-radius: 50px; background-color: rgb(28, 28, 28); }

.ns-lletm-e-10 { color: rgb(255, 255, 255); white-space: nowrap; }

.ns-lletm-e-12 { background-image: url("https://tpc.googlesyndication.com/simgad/18098778687903435156/14763004658117789537?sqp=-oaymwEMIAUqCCgWME44AEBk&rs=AOga4qmftJH-Htl0f7X_-9muBNprCXHBtw"); background-repeat: no-repeat; background-size: contain; }
------MultipartBoundary--gTeBJSadrSfB9fkoA1ZM7LaQjuvZHVR8uDTTrt6Ltc----
Content-Type: text/css
Content-Transfer-Encoding: binary
Content-Location: cid:css-f5efd835-8222-462e-a7c3-a69613b833d9@mhtml.blink

@charset "utf-8";

.ns-lletm-l-landscapePortraitImageLayout { opacity: 0.01; position: absolute; top: 0px; left: 0px; display: block; width: 384px; height: 340px; }

.ns-lletm-e-0 { box-sizing: border-box; height: 100%; width: 100%; font-family: "Open Sans", sans-serif; font-size: 16px; }

.ns-lletm-e-1 { box-sizing: border-box; width: 100%; height: 100%; }

.ns-lletm-e-2 { box-sizing: border-box; position: absolute; top: 0px; left: 0px; height: 100%; width: 196.15px; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; padding: 12px; }

.ns-lletm-e-3 { box-sizing: border-box; display: flex; width: 100%; font-weight: 700; }

.ns-lletm-e-5 { box-sizing: border-box; display: flex; font-weight: 200; flex-direction: column; align-items: center; justify-content: center; margin: 12px 0px; }

.ns-lletm-e-7 { box-sizing: border-box; width: 100%; flex-grow: 1; }

.ns-lletm-e-8 { box-sizing: border-box; margin-top: 12px; width: 100%; }

.ns-lletm-e-9 { display: flex; padding: 8px 12px; flex-direction: column; justify-content: center; align-items: center; white-space: nowrap; }

.ns-lletm-e-11 { position: absolute; top: 0px; right: 0px; width: 187.85px; height: 100%; display: block; }

.ns-lletm-e-12 { display: block; flex-shrink: 0; flex-grow: 0; max-width: 663px; max-height: 1200px; width: 100%; height: 100%; }

.ns-lletm-v-0 .ns-lletm-e-3 { font-size: 28px; }

.ns-lletm-v-0 .ns-lletm-e-5 { font-size: 16px; }

.ns-lletm-v-0 .ns-lletm-e-9 { font-size: 18px; }
------MultipartBoundary--gTeBJSadrSfB9fkoA1ZM7LaQjuvZHVR8uDTTrt6Ltc----
Content-Type: text/css
Content-Transfer-Encoding: binary
Content-Location: cid:css-ba9d64f4-4fdf-47f9-afbd-819f0b315986@mhtml.blink

@charset "utf-8";

html, body { height: 100%; width: 100%; margin: 0px; padding: 0px; overflow: hidden; }

#mys-wrapper { height: 100%; width: 100%; overflow: hidden; position: absolute; top: 0px; left: 0px; align-items: center; display: flex; justify-content: center; line-height: normal; }

#mys-overlay { height: 100%; width: 100%; overflow: hidden; position: absolute; top: 0px; left: 0px; box-sizing: border-box; pointer-events: none; z-index: 1; display: none; }

.mys-wrapper a, .mys-wrapper a:visited, .mys-wrapper a:hover, .mys-wrapper a:active { color: inherit; cursor: pointer; text-decoration: inherit; }

[dir="rtl"] .flip-on-rtl { transform: scale(-1, 1); transform-origin: center center; }

#mys-content { flex-shrink: 0; position: relative; overflow: hidden; z-index: 0; }
